using System;
using System.IO;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using Object=UnityEngine.Object;
namespace CoastalFactory.Editor {public static partial class LeftFactoryDistrictBuilder {
[MenuItem("Anseong/Art/Apply Industrial Ground Surface")]
public static void ApplyIndustrialGroundSurface(){EditorSceneManager.OpenScene(Scene);const string folder="Assets/_Anseong/Art/Environment/GroundSurface";AssetDatabase.Refresh();string texturePath=folder+"/IndustrialConcrete_Albedo.png";var importer=(TextureImporter)AssetImporter.GetAtPath(texturePath);if(!importer)throw new Exception("Missing concrete texture");importer.textureType=TextureImporterType.Default;importer.sRGBTexture=true;importer.alphaSource=TextureImporterAlphaSource.None;importer.mipmapEnabled=true;importer.wrapMode=TextureWrapMode.Repeat;importer.filterMode=FilterMode.Trilinear;importer.anisoLevel=4;importer.maxTextureSize=1024;importer.textureCompression=TextureImporterCompression.Compressed;importer.compressionQuality=70;importer.isReadable=false;importer.SaveAndReimport();var texture=AssetDatabase.LoadAssetAtPath<Texture2D>(texturePath);var shader=Shader.Find("Anseong/LightweightIndustrialGround");if(!shader||ShaderUtil.ShaderHasError(shader))throw new Exception("Ground shader invalid");var mat=new Material(shader);mat.name="IndustrialGround_Shared";mat.SetTexture("_BaseMap",texture);mat.enableInstancing=true;AssetDatabase.CreateAsset(mat,folder+"/IndustrialGround_Shared.mat");int applied=0;foreach(var name in new[]{"ContinuousLandSurface","IndustrialApron_BaseMaterialOnly"}){var g=GameObject.Find(name);if(!g)throw new Exception("Ground object missing: "+name);var renderer=g.GetComponent<MeshRenderer>();var materials=renderer.sharedMaterials;for(int i=0;i<materials.Length;i++)materials[i]=mat;renderer.sharedMaterials=materials;applied++;}File.WriteAllText(folder+"/README.md","# Lightweight industrial concrete ground\n\nApply/replace IndustrialGround_Shared.mat on ContinuousLandSurface and IndustrialApron_BaseMaterialOnly. One1024x1024 compressed mipmapped albedo texture, shared material, worldXZ mapping(8m repeat) so no UV rebuild needed. Subtle6m expansion joints and45m dust variation are procedural arithmetic, no extra texture samplers. No normal/parallax/displacement maps, decals, realtime reflection, added ground meshes, colliders or scripts. Shader uses main light/shadows and fog. Texture swap, tint, repeat scale and joint/dust strength are material properties. Roads, sea, sand, terrain hills unchanged. VR performance not measured.\n\nTexture produced with built-in image generation: seamless top-down neutral grey steelworks yard concrete, fine aggregate, faint rubber/dust wear, low contrast, no objects or baked shadows. Source image resized by Unity importer to1024, no image-processing edits.\n");AssetDatabase.Refresh();AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),Scene);Capture(Camera.main,"GroundSurface_Main");var go=new GameObject("GroundSurfacePreview");var cam=go.AddComponent<Camera>();cam.CopyFrom(Camera.main);cam.transform.position=new Vector3(10,28,-70);cam.transform.LookAt(new Vector3(15,0,-20));Capture(cam,"GroundSurface_Close");Object.DestroyImmediate(go);Debug.Log("INDUSTRIAL_GROUND_PASS renderers="+applied+" texture="+texture.width+"x"+texture.height+" format="+texture.format+" sharedMaterial=true textureSamplers=1 noExtraGeometry=true");}
}}